steps.script:
for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		t.queue_free()
ToastManager.active_toasts.clear()
TutorialManager._last_block_toast_ms = 0
return ToastManager.active_toasts.size()

var texts = []
for toast in ToastManager.active_toasts:
	if not is_instance_valid(toast):
		continue
	for c in toast.get_children():
		if c is Label:
			texts.append(c.text)
return " | ".join(PackedStringArray(texts))

var found = false
for toast in ToastManager.active_toasts:
	if not is_instance_valid(toast):
		continue
	for c in toast.get_children():
		if c is Label and "Continue" in c.text:
			found = true
return found

var echoed = false
for toast in ToastManager.active_toasts:
	if not is_instance_valid(toast):
		continue
	for c in toast.get_children():
		if c is Label and "OI, LISTEN UP" in c.text:
			echoed = true
return echoed

var clean = true
for toast in ToastManager.active_toasts:
	if not is_instance_valid(toast):
		continue
	for c in toast.get_children():
		if c is Label and ("{a}" in c.text or "  " in c.text):
			clean = false
return clean

for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		t.queue_free()
ToastManager.active_toasts.clear()
TutorialManager._last_block_toast_ms = 0
return ToastManager.active_toasts.size()

var found = false
for toast in ToastManager.active_toasts:
	if not is_instance_valid(toast):
		continue
	for c in toast.get_children():
		if c is Label and "Continue" in c.text and "Pickin' anuvver unit" in c.text:
			found = true
return found

var echoed = false
for toast in ToastManager.active_toasts:
	if not is_instance_valid(toast):
		continue
	for c in toast.get_children():
		if c is Label and "READ DA BAR" in c.text:
			echoed = true
return echoed

var ok = false
for toast in ToastManager.active_toasts:
	if not is_instance_valid(toast):
		continue
	for c in toast.get_children():
		if c is Label and not ("{a}" in c.text) and "press " in c.text:
			ok = true
return ok
